    async def validate_partitioning_schema(
        self,
        *,
        zone: str | None = None,
        partitioning_schema: Schema | None = None,
        offer_id: str | _Ref[Any] | None = None,
        os_id: str | _Ref[Any] | None = None,
    ) -> None:
        """
        Validate client partitioning schema

        Validate the incoming partitioning schema from a user before installing the
        server. Return default ErrorCode if invalid.
        """
        await self._session.api(_BaremetalAPI).validate_partitioning_schema(
            zone=zone,
            partitioning_schema=partitioning_schema,
            offer_id=None if offer_id is None else _identifier(offer_id),
            os_id=None if os_id is None else _identifier(os_id),
        )
